function evaluateProperty({api, helpers}) {
	return api.data.playbook_activity_ui.playbookCardProperties.activityState.value !== "IN_PROGRESS" ? "style-class-1" : "";
}

targets.clientTransformScript:
javascript(/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
*/
function evaluateEvent({api, event}) {
	const sessionType = api.state?.sessionType;
	return {
		event: sessionType === 'bulk_app_update' ? 'Complete upgrade in Bulk Update' : 'Complete upgrade',
		value: {
			'Session id': api.state.upgradeSessionId,
			'Source patch': api.state.sourceVersion,
			'Target patch': api.state.targetVersion
		}
	};
})

